with valid as (select *, date_format(sale_date, 'yyyy-MM') as sale_date_label from store_sales where sale_date >= to_date('2023-07-24')), enriched as (select src.*, b.city, b.region, b.sqft from valid src inner join stores b on src.store_id = b.id where b.city not in ('Bangkok', 'Singapore')), filtered as (select id, store_id, product_id, sale_date, units, revenue, city, region, sqft, concat(region, ' ', city) as region_city from enriched where city is not null and region != 'West'), matched_keys as (select id from filtered except all select id from store_sales where product_id in (7, 8, 9, 10)), kept_rows as (select s.* from filtered s inner join matched_keys k on s.id = k.id), filtered_store_sales as (select id, store_id, product_id, sale_date, units, revenue, city, sqft, revenue - units as revenue_per_unit, revenue - sqft as revenue_minus_sqft, coalesce(city, 'DIRECT') as city_filled from kept_rows where region is not null and sale_date >= to_date('2023-02-14')), joined as (select src.product_id, src.units, src.city, src.sqft, src.revenue_minus_sqft, src.city_filled, p.stock_qty, p.launch_date, p.cost from filtered_store_sales src left join products p on src.product_id = p.id), summary as (select case when revenue_minus_sqft >= 79 then 'LARGE' else 'SMALL' end as revenue_minus_sqft_tier, case when sqft >= 15346 then 'HIGH' else 'LOW' end as sqft_tier, size(collect_set(city)) as num_cities, size(collect_set(city)) as num_cities_2, sum(case when city = 'Tokyo' then cost else 0 end) as tokyo_cost from joined group by case when revenue_minus_sqft >= 79 then 'LARGE' else 'SMALL' end, case when sqft >= 15346 then 'HIGH' else 'LOW' end having sum(case when city = 'Tokyo' then cost else 0 end) < 1000000) select revenue_minus_sqft_tier, sqft_tier, num_cities, num_cities_2, tokyo_cost from summary order by revenue_minus_sqft_tier, tokyo_cost;
